double capacitorVoltageAfterStep(double sourceVoltage, double resistanceOhms, double capacitanceFarads, double elapsedSeconds) {
    // A constante de tempo define a escala temporal do carregamento.
    double timeConstant = resistanceOhms * capacitanceFarads;
    return sourceVoltage * (1.0 - exp(-elapsedSeconds / timeConstant));
}
